import sys

def is_magical(n):
    s = str(n)
    total = 0
    for i in range(1, 1 << len(s)):
        product = 1
        for j in range(len(s)):
            if i & (1 << j):
                product *= int(s[j])
        total += product
    return total % 2 == 0

def find_kth_magical(k):
    count = 0
    num = 0
    while count < k:
        if is_magical(num):
            count += 1
        if count == k:
            return num
        num += 1

input = sys.stdin.read().split()
t = int(input[0])
results = []
index = 1
for _ in range(t):
    k = int(input[index])
    results.append(find_kth_magical(k))
    index += 1

for result in results:
    print(result)
